/* SPDX-License-Identifier: GPL-3.0-only */
/* Host proof: Chicago EQ insert tilts spectrum vs dry native303. */
#include <math.h>
#include <stdio.h>
#include <string.h>
#include "bass303.h"
#include "chicago_eq.h"
#include "chicago_fx.h"

static int fails;
#define CHECK(c, ...)                                                                                                  \
    do {                                                                                                               \
        if (!(c)) {                                                                                                    \
            printf("FAIL " __VA_ARGS__);                                                                               \
            printf("\n");                                                                                              \
            fails++;                                                                                                   \
        }                                                                                                              \
    } while (0)

static float buf[8192];
static float dry[8192];

static void render_note(bass303_t *b, float *out, int n)
{
    int pos = 0;
    bass303_init(b);
    bass303_set(b, BASS303_CUTOFF, 100);
    bass303_set(b, BASS303_RESO, 40);
    bass303_set(b, BASS303_ENVMOD, 0);
    bass303_set(b, BASS303_WAVE, 0);
    bass303_set(b, BASS303_GNAW, 0);
    bass303_set(b, BASS303_BITE, 0);
    bass303_set(b, BASS303_VOLUME, 100);
    bass303_set(b, BASS303_DRIVE, 0);
    bass303_set(b, BASS303_AMPMODE, BASS303_AMP_GATE);
    bass303_note_on_velocity(b, 48, 0, 0, 100);
    while (pos < n) {
        int m = n - pos > 128 ? 128 : n - pos;
        bass303_render(b, out + pos, m);
        pos += m;
    }
}

static double rms_delta(const float *a, const float *b, int n)
{
    double s = 0;
    int i;
    for (i = 0; i < n; i++) {
        double d = (double)a[i] - (double)b[i];
        s += d * d;
    }
    return sqrt(s / (double)n);
}

/* Crude highband energy: sum |x[i]-x[i-1]| (bright EQ raises this). */
static double edge_energy(const float *x, int n)
{
    double s = 0;
    int i;
    for (i = 1; i < n; i++)
        s += fabs((double)x[i] - (double)x[i - 1]);
    return s / (double)n;
}

static void test_supported_flags(void)
{
    CHECK(chi_fx_supported(CHI_FX_EQ), "EQ supported");
    CHECK(chi_fx_is_insert(CHI_FX_EQ), "EQ is insert");
    CHECK(chi_fx_is_eq_insert(CHI_FX_EQ), "EQ eq-insert helper");
    CHECK(!chi_fx_is_not_yet(CHI_FX_EQ), "EQ not NOT_YET");
    CHECK(strstr(CHI_FX_TYPE_N[CHI_FX_EQ], "—") == 0, "EQ label has no em-dash");
}

static void test_map_clears_sends(void)
{
    chicago_fx_out_t o;
    chicago_fx_map(CHI_FX_EQ, 0, 127, 0, &o);
    CHECK(o.touch == CHI_FX_W_CLEAR_SENDS, "EQ insert clears sends");
    CHECK(!(o.touch & CHI_FX_W_COMP), "EQ does not set Comp");
    CHECK(!(o.touch & CHI_FX_W_DIST), "EQ does not set Dist");
    CHECK(!(o.touch & CHI_FX_W_MX_DLY), "EQ does not set Mix delay");
}

static void test_tilt_and_wet0(void)
{
    bass303_t b;
    chi_eq_t eq;
    int n = 4096, skip = 512;
    double dark_edge, bright_edge, delta;
    render_note(&b, dry, n);

    memcpy(buf, dry, (size_t)n * sizeof(float));
    chi_eq_init(&eq);
    chi_eq_set(&eq, 0, 127, BASS303_SR); /* dark + full wet */
    chi_eq_process(&eq, buf + skip, n - skip);
    dark_edge = edge_energy(buf + skip, n - skip);
    delta = rms_delta(dry + skip, buf + skip, n - skip);
    CHECK(delta > 1e-4, "dark EQ changes waveform (rms delta %g)", delta);

    memcpy(buf, dry, (size_t)n * sizeof(float));
    chi_eq_init(&eq);
    chi_eq_set(&eq, 127, 127, BASS303_SR); /* bright + full wet */
    chi_eq_process(&eq, buf + skip, n - skip);
    bright_edge = edge_energy(buf + skip, n - skip);
    CHECK(bright_edge > dark_edge * 1.05, "bright EQ has more edge energy (dark %g bright %g)", dark_edge,
          bright_edge);

    memcpy(buf, dry, (size_t)n * sizeof(float));
    chi_eq_init(&eq);
    chi_eq_process(&eq, buf + skip, n - skip);
    CHECK(memcmp(buf + skip, dry + skip, (size_t)(n - skip) * sizeof(float)) == 0, "unset EQ leaves PCM unchanged");
}

int main(void)
{
    test_supported_flags();
    test_map_clears_sends();
    test_tilt_and_wet0();
    if (fails) {
        printf("%d FAIL(s)\n", fails);
        return 1;
    }
    printf("PASS chicago_eq\n");
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Independent production replay: a rejected feedback write must retry, and a
 * dropped unrelated release must never turn a held Pause repeat into a press. */
#include <stdint.h>
#include <string.h>
static unsigned attempted, accepted, fail_note, failure_enabled;
static uint8_t last_ok[3];
int plat_ble_smc_send(const uint8_t *m, uint8_t n)
{
    attempted++;
    if (failure_enabled && n == 3 && m[0] == 0x90 && m[1] == fail_note) return 0;
    accepted++;
    if (n == 3) memcpy(last_ok, m, 3);
    return 1;
}
#define SMC_UI_SEND_IMPLEMENTED 1
#define SMC_UI_MAIN smc_ui_replay_main
#include "smc_ui_test.c"

static void send_note(int host, unsigned note, unsigned status, unsigned velocity)
{
    if (!host) message(status, note, velocity);
    else {
        CHECK(smc_midi_host((status == 0x80 ? 8u : 9u) |
            (status | 15u) << 8 | note << 16 | velocity << 24));
        smc_poll();
    }
}
static void queue_lost_release(int host, unsigned note, unsigned status)
{
    if (host) {
        for (unsigned i = 0; i < SMC_Q; i++)
            CHECK(smc_midi_host(11u | 0xBFu << 8 | 16u << 16));
        CHECK(smc_midi_host((status == 0x80 ? 8u : 9u) | (status | 15u) << 8 | note << 16));
    } else {
        const uint8_t filler[3] = {0xB0, 16, 0};
        const uint8_t release[3] = {(uint8_t)status, (uint8_t)note, 0};
        for (unsigned i = 0; i < SMC_Q; i++) smc_ble_midi(filler, 3);
        smc_ble_midi(release, 3);
    }
    smc_poll();
}
static void feedback_retry(void)
{
    setup(V_SEQ, PART_808); smc_frame();
    seq.ext_now = smc.beat_at + smc.beat_period / 2u; smc_frame();
    CHECK(smc.known[0x5D] && !smc.lit[0x5D]);
    unsigned before = accepted;
    fail_note = 0x5D; failure_enabled = 1; seq.ext_now = smc.beat_at + smc.beat_period; smc_frame();
    CHECK(accepted == before && !smc.lit[0x5D]);
    smc_frame(); CHECK(accepted == before && !smc.lit[0x5D]);
    failure_enabled = 0; smc_frame();
    CHECK(accepted == before + 1 && smc.lit[0x5D]);
    CHECK(last_ok[0] == 0x90 && last_ok[1] == 0x5D && last_ok[2] == 127);
    send_note(0, 0x5D, 0x90, 127); send_note(0, 0x5D, 0x90, 0);
    CHECK(smc.locked); seq.ext_now += smc.beat_period / 2u; smc_frame(); CHECK(smc.lit[0x5D]);
    send_note(0, 0x5D, 0x90, 127); CHECK(smc.locked);
    now_ms += 900; smc_poll(); send_note(0, 0x5D, 0x90, 0);
    CHECK(!smc.locked); smc_frame(); CHECK(!smc.lit[0x5D]);
    puts("PASS independent LED backpressure: rejected write retries; cache tracks accepted bytes; lock/unlock phases");
}
static void independent_release_loss(void)
{
    const unsigned unrelated[3] = {8, 24, 0x5E};
    for (int host = 0; host < 2; host++) for (int type = 0; type < 2; type++) {
        unsigned status = type ? 0x80 : 0x90;
        for (unsigned n = 0; n < 3; n++) {
            setup(V_SEQ, PART_909); proj.set.bt |= PROJ_BT_SMC_USER;
            send_note(host, 0x5D, 0x90, 127); CHECK(smc.locked && smc.lock_down);
            pref_t captured = smc_target(0);
            queue_lost_release(host, unrelated[n], status);
            CHECK(smc.locked && smc.lock_down);
            send_note(host, 0x5D, 0x90, 127);
            CHECK(smc.locked && smc_same(captured, smc_target(0)));
            send_note(host, 0x5D, status, 0); CHECK(smc.locked && !smc.lock_down);
            send_note(host, 0x5D, 0x90, 127); CHECK(smc.locked);
            now_ms += 900; smc_poll(); CHECK(!smc.locked);
            send_note(host, 0x5D, status, 0); CHECK(!smc.locked && !smc.lock_down);
        }
        setup(V_SEQ, PART_808); proj.set.bt |= PROJ_BT_SMC_USER;
        send_note(host, 0x5D, 0x90, 127); CHECK(smc.locked);
        /* Publication rollover is ordinary modulo arithmetic, not a stale loss. */
        smc_pause_release_lost[host] = smc_pause_release_seen[host] = UINT32_MAX;
        queue_lost_release(host, 0x5D, status);
        CHECK(smc.locked && !smc.lock_down);
        CHECK(!smc_pause_release_lost[host] && !smc_pause_release_seen[host]);
        send_note(host, 0x5D, 0x90, 127); CHECK(smc.locked);
        now_ms += 900; smc_poll(); CHECK(!smc.locked);
        send_note(host, 0x5D, status, 0);
    }
    puts("PASS independent Pause release ownership: BLE/host, NoteOff/zero, unrelated Solo/Select/Play losses, actual Pause loss and epoch wrap");
}
int main(void)
{
    feedback_retry(); independent_release_loss();
    printf("smc_pause_loss: PASS (%u independent production checks)\n", checks);
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Product-sound identity codec. Callers own storage/adoption transactions.
 * Registry entries must use the current backend's existing engine ID, but schema
 * describes the complete product T_303 surface, not the smaller DSP-only schema.
 * The integration owner supplies the registry from actual production descriptors. */
#pragma once
#include <stddef.h>
#include <stdint.h>

#define BASS_IDENTITY_BYTES 8u
#define BASS_IDENTITY_PRODUCT_SCHEMA 1u
#define BASS_IDENTITY_LAST_UNTAGGED_SOUND_REV 10u

enum { BASS_IDENTITY_UNKNOWN = 0, BASS_IDENTITY_KNOWN = 1 };
enum {
    BASS_IDENTITY_READY = 0,
    BASS_IDENTITY_CHOICE_REQUIRED,
    BASS_IDENTITY_UNSUPPORTED,
    BASS_IDENTITY_UNAVAILABLE,
    BASS_IDENTITY_INVALID
};
typedef struct {
    uint32_t engine;
    uint16_t schema;
    uint8_t count, state;
} bass_identity_t;
typedef struct {
    uint32_t engine;
    uint16_t schema;
    uint8_t count, available;
} bass_identity_entry_t;

/* Count/schema mismatches and conflicting registry rows never admit a sound.
 * An unavailable known engine remains distinct from an invalid or unknown tag. */
static inline int bass_identity_check(const bass_identity_t *tag,
                                     const bass_identity_entry_t *registry, size_t n)
{
    const bass_identity_entry_t *match = NULL;
    size_t i;
    if (!tag || (!registry && n)) return BASS_IDENTITY_INVALID;
    if (tag->state == BASS_IDENTITY_UNKNOWN)
        return !tag->engine && !tag->schema && !tag->count ?
            BASS_IDENTITY_CHOICE_REQUIRED : BASS_IDENTITY_INVALID;
    if (tag->state != BASS_IDENTITY_KNOWN || !tag->engine || !tag->schema || !tag->count)
        return BASS_IDENTITY_INVALID;
    for (i = 0; i < n; i++) {
        const bass_identity_entry_t *row = &registry[i];
        if (!row->engine || !row->schema || !row->count || row->available > 1)
            return BASS_IDENTITY_INVALID;
        if (row->engine != tag->engine || row->schema != tag->schema) continue;
        if (match && (match->count != row->count || match->available != row->available))
            return BASS_IDENTITY_INVALID;
        match = row;
    }
    if (!match) return BASS_IDENTITY_UNSUPPORTED;
    if (tag->count != match->count) return BASS_IDENTITY_INVALID;
    return match->available ? BASS_IDENTITY_READY : BASS_IDENTITY_UNAVAILABLE;
}

static inline int bass_identity_decode(bass_identity_t *out, const uint8_t *wire, size_t bytes,
                                      const bass_identity_entry_t *registry, size_t n)
{
    bass_identity_t tag;
    int status;
    if (!out || !wire || bytes != BASS_IDENTITY_BYTES) return BASS_IDENTITY_INVALID;
    tag.engine = (uint32_t)wire[0] | (uint32_t)wire[1] << 8 |
                 (uint32_t)wire[2] << 16 | (uint32_t)wire[3] << 24;
    tag.schema = (uint16_t)((uint16_t)wire[4] | (uint16_t)wire[5] << 8);
    tag.count = wire[6]; tag.state = wire[7];
    status = bass_identity_check(&tag, registry, n);
    if (status != BASS_IDENTITY_INVALID) *out = tag;
    return status;
}

/* Unknown future tags are retained as their original bytes, never rewritten by
 * this encoder. Write only canonical known/known-unavailable or empty tags. */
static inline int bass_identity_encode(uint8_t *wire, size_t bytes, const bass_identity_t *tag,
                                      const bass_identity_entry_t *registry, size_t n)
{
    int status = bass_identity_check(tag, registry, n);
    if (!wire || bytes != BASS_IDENTITY_BYTES) return BASS_IDENTITY_INVALID;
    if (status != BASS_IDENTITY_READY && status != BASS_IDENTITY_UNAVAILABLE &&
        status != BASS_IDENTITY_CHOICE_REQUIRED) return status;
    wire[0] = (uint8_t)tag->engine; wire[1] = (uint8_t)(tag->engine >> 8);
    wire[2] = (uint8_t)(tag->engine >> 16); wire[3] = (uint8_t)(tag->engine >> 24);
    wire[4] = (uint8_t)tag->schema; wire[5] = (uint8_t)(tag->schema >> 8);
    wire[6] = tag->count; wire[7] = tag->state;
    return status;
}

/* No voice-index, value-range, producer-version or snapshot inference. The caller
 * owns a separate tag output; the original sound/export is not an argument. */
static inline int bass_identity_legacy(unsigned sound_revision, bass_identity_t *out)
{
    bass_identity_t unknown = {0, 0, 0, BASS_IDENTITY_UNKNOWN};
    if (!out) return BASS_IDENTITY_INVALID;
    if (sound_revision > BASS_IDENTITY_LAST_UNTAGGED_SOUND_REV)
        return BASS_IDENTITY_UNSUPPORTED;
    *out = unknown;
    return BASS_IDENTITY_CHOICE_REQUIRED;
}

/* Sound revision 11: eight canonical identity bytes, LE preset index, flags,
 * reserved zero. All-zero unknown is distinct from a named factory preset. */
#define BASS_SOUND_TAG_BYTES 12u
#define BASS_SOUND_NO_PRESET 0xffffu
#define BASS_SOUND_EDITED 1u
typedef struct { uint8_t bytes[BASS_SOUND_TAG_BYTES]; } bass_sound_tag_t;
typedef struct {
    bass_identity_t identity;
    uint16_t preset;
    uint8_t flags;
} bass_sound_info_t;
static inline int bass_sound_tag_decode(bass_sound_info_t *out,const bass_sound_tag_t *wire,
                                       const bass_identity_entry_t *registry,size_t n)
{
    bass_sound_info_t info;
    int rc;
    if(!out || !wire)return BASS_IDENTITY_INVALID;
    rc=bass_identity_decode(&info.identity,wire->bytes,BASS_IDENTITY_BYTES,registry,n);
    if(rc==BASS_IDENTITY_INVALID || rc==BASS_IDENTITY_UNSUPPORTED)return rc;
    info.preset=(uint16_t)(wire->bytes[8]|((uint16_t)wire->bytes[9]<<8));
    info.flags=wire->bytes[10];
    if(wire->bytes[11] || (info.flags&~BASS_SOUND_EDITED))return BASS_IDENTITY_INVALID;
    if(rc==BASS_IDENTITY_CHOICE_REQUIRED) {
        if(info.preset || info.flags)return BASS_IDENTITY_INVALID;
    } else if(info.preset==BASS_SOUND_NO_PRESET && info.flags!=BASS_SOUND_EDITED)return BASS_IDENTITY_INVALID;
    *out=info;return rc;
}
static inline int bass_sound_tag_encode(bass_sound_tag_t *out,const bass_sound_info_t *info,
                                       const bass_identity_entry_t *registry,size_t n)
{
    bass_sound_tag_t wire={{0}};bass_sound_info_t check;
    if(!out || !info)return BASS_IDENTITY_INVALID;
    int rc=bass_identity_encode(wire.bytes,BASS_IDENTITY_BYTES,&info->identity,registry,n);
    if(rc!=BASS_IDENTITY_READY && rc!=BASS_IDENTITY_UNAVAILABLE && rc!=BASS_IDENTITY_CHOICE_REQUIRED)return rc;
    wire.bytes[8]=(uint8_t)info->preset;wire.bytes[9]=(uint8_t)(info->preset>>8);wire.bytes[10]=info->flags;
    int valid=bass_sound_tag_decode(&check,&wire,registry,n);
    if(valid==BASS_IDENTITY_INVALID)return valid;
    *out=wire;return rc;
}

